pattern(p,c){const graph=svg(p,'Patron coté et lignes de pliage');if(c.kind==='notch'){const n=range(p,'Largeur de l’encoche (mm)',2,20,4);on([n],()=>{const a=(60-+n.value)/2;graph.innerHTML=`<g transform="translate(90 35) scale(6)"><path d="M0 0H${a}V15H${a+ +n.value}V0H60V30H0Z" fill="#e2edd9" stroke="#356e5d" stroke-width=".5"/></g><text x="90" y="255">Pièce 60 × 30 mm · encoche ${n.value} × 15 mm</text>`})}else if(c.kind==='hinge'){const fold=range(p,'Position du pli sur la largeur (mm)',2,18,10);on([fold],()=>{graph.innerHTML=`<rect x="70" y="60" width="480" height="120" fill="#e1ebd5" stroke="#356e5d" stroke-width="3"/><path d="M70 ${60+ +fold.value*6}H550" stroke="#235879" stroke-dasharray="8 5" stroke-width="3"/><text x="70" y="225">Bande 80 × 20 mm · pli à ${fold.value} mm du bord</text>`})}else{const total=c.total,width=c.width;const a=range(p,'Premier pli ('+c.unit+')',1,total-2,c.a),b=range(p,'Second pli ('+c.unit+')',2,total-1,c.b);const out=output(p);on([a,b],()=>{const k=480/total;graph.innerHTML=`<rect x="60" y="55" width="480" height="140" fill="#e1ebd5" stroke="#356e5d" stroke-width="3"/><path d="M${60+ +a.value*k} 55V195 M${60+ +b.value*k} 55V195" stroke="#235879" stroke-dasharray="8 5" stroke-width="3"/><text x="60" y="235">Bande ${width} × ${total} ${c.unit}</text>`;out.textContent=+a.value<+b.value?'Positions depuis le même bord : '+a.value+' et '+b.value+' '+c.unit+'.':'Les deux plis se croisent dans la numérotation : replace le premier avant le second.';})}p.append(E('p','Le dessin à l’écran n’est pas à taille réelle. Utilise les cotes et une règle pour tracer sur papier. Un patron ne garantit pas la stabilité de l’objet fabriqué.','hint'))},
energy(p,c){const capacity=select(p,'Stockage étudié',c.stores.map(([n,v],i)=>[i,n+' · '+v+' '+c.unit]));const solar=c.solar?range(p,'Recharge par jour (Wh)',0,5,0):null;let left=c.stores[+capacity.value][1],day=0;const graph=svg(p,'Évolution du stock disponible');const out=output(p);const draw=()=>{if(solar)solar.disabled=+capacity.value!==c.stores.length-1;const ratio=Math.max(0,left/c.stores[+capacity.value][1]);graph.innerHTML=`<rect x="70" y="70" width="480" height="90" rx="12" fill="#e8ece2" stroke="#3a7163" stroke-width="3"/><rect x="75" y="75" width="${470*ratio}" height="80" rx="8" fill="#83b596"/><text x="70" y="215">${c.timeLabel||'Jour'} ${day} · stock ${fmt(left)} ${c.unit}</text>`;out.textContent='Stock restant : '+fmt(left)+' '+c.unit+'.'};button(p,c.stepLabel||'Avancer d’un jour',()=>{day++;left=Math.max(0,Math.min(c.stores[+capacity.value][1],left+(solar&&+capacity.value===c.stores.length-1?+solar.value:0))-c.use);draw()});button(p,'Recommencer avec le stockage choisi',()=>{left=c.stores[+capacity.value][1];day=0;draw()});capacity.addEventListener('change',()=>{left=c.stores[+capacity.value][1];day=0;draw()});draw();p.append(E('p',c.note,'hint'))},
